/**
 * Merge every feed item, tag the source, drop unusable rows, dedupe by
 * canonical URL, and keep only items published in the lookback window
 * (default: 48 hours). Failures on a single feed are recorded, not fatal.
 */
function readEnv(name, fallback) {
  try {
    const bag = (typeof $env !== 'undefined') ? $env : {};
    const value = bag[name];
    if (value == null || value === '') return fallback == null ? '' : fallback;
    return String(value);
  } catch {
    return fallback == null ? '' : fallback;
  }
}

const LOOKBACK_HOURS = Number(readEnv('LOOKBACK_HOURS', '48')) || 48;
const cutoffMs = Date.now() - LOOKBACK_HOURS * 60 * 60 * 1000;

const EXPECTED_FEEDS = [
  { source_name: 'OpenAI News', feed_url: 'https://openai.com/news/rss.xml', hostIncludes: ['openai.com'] },
  { source_name: 'Google DeepMind', feed_url: 'https://www.deepmind.com/blog/rss.xml', hostIncludes: ['deepmind.google', 'deepmind.com'] },
  { source_name: 'Google AI Blog', feed_url: 'https://blog.google/technology/ai/rss/', hostIncludes: ['blog.google'] },
  { source_name: 'Hugging Face Blog', feed_url: 'https://huggingface.co/blog/feed.xml', hostIncludes: ['huggingface.co'] },
  { source_name: 'arXiv cs.AI', feed_url: 'https://rss.arxiv.org/rss/cs.AI', hostIncludes: ['arxiv.org'] },
];

function stripHtml(value) {
  return String(value || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/g, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/\s+/g, ' ')
    .trim();
}

function canonUrl(raw) {
  if (!raw) return '';
  try {
    const url = new URL(String(raw).trim());
    url.hash = '';
    for (const key of [...url.searchParams.keys()]) {
      if (key.toLowerCase().startsWith('utm_') || key === 'fbclid' || key === 'ref') {
        url.searchParams.delete(key);
      }
    }
    let href = url.toString();
    if (href.endsWith('/') && url.pathname !== '/') href = href.slice(0, -1);
    url.protocol = 'https:';
    href = url.toString();
    if (href.endsWith('/') && url.pathname !== '/') href = href.slice(0, -1);
    return href;
  } catch {
    return String(raw).trim();
  }
}

function parseDate(value) {
  if (!value) return null;
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? null : date;
}

function inferSource(item) {
  if (item.source_name) return { source_name: item.source_name, feed_url: item.feed_url || '' };
  const url = String(item.link || item.guid || item.id || item.feed_url || '');
  let host = '';
  try { host = new URL(url).hostname.replace(/^www\./, ''); } catch { /* ignore */ }
  const match = EXPECTED_FEEDS.find((feed) => feed.hostIncludes.some((h) => host.includes(h)));
  if (match) return match;
  return { source_name: host || 'Unknown source', feed_url: item.feed_url || '' };
}

function extractItem(raw) {
  const title = stripHtml(raw.title || '');
  const url = canonUrl(raw.link || raw.guid || raw.id || '');
  const published = parseDate(raw.isoDate || raw.pubDate || raw.updated || raw.published || raw.date);
  const chunks = [];
  for (const rawChunk of [raw.contentSnippet, raw.content, raw.summary, raw.description, raw['content:encoded']]) {
    const chunk = stripHtml(rawChunk);
    if (!chunk) continue;
    if (chunks.some((existing) => existing === chunk || existing.includes(chunk))) continue;
    // If the new chunk is a longer version of an earlier one, replace it.
    const idx = chunks.findIndex((existing) => chunk.includes(existing));
    if (idx >= 0) chunks[idx] = chunk;
    else chunks.push(chunk);
  }
  const content = chunks.join(' ').slice(0, 8000);
  return { title, url, published, content };
}

const feedHealthMap = new Map(EXPECTED_FEEDS.map((f) => [f.source_name, {
  source_name: f.source_name,
  feed_url: f.feed_url,
  status: 'no_items',
  item_count: 0,
  error: null,
}]));

const incoming = $input.all().map((row) => row.json);
const kept = [];
const seen = new Set();
let droppedNoUrlOrTitle = 0;
let droppedOutsideWindow = 0;
let droppedDuplicate = 0;
let droppedUndated = 0;

for (const raw of incoming) {
  const inferred = inferSource(raw);
  const health = feedHealthMap.get(inferred.source_name) || {
    source_name: inferred.source_name,
    feed_url: inferred.feed_url,
    status: 'ok',
    item_count: 0,
    error: null,
  };

  const looksLikeError = Boolean(raw.error) || Boolean(raw.message && !raw.title && !raw.link);
  if (looksLikeError) {
    health.status = 'error';
    health.error = stripHtml(raw.error?.message || raw.error || raw.message || 'Feed request failed');
    feedHealthMap.set(health.source_name, health);
    continue;
  }

  const item = extractItem(raw);
  if (!item.url || !item.title) {
    droppedNoUrlOrTitle += 1;
    continue;
  }
  if (!item.published) {
    droppedUndated += 1;
    continue;
  }
  if (item.published.getTime() < cutoffMs) {
    droppedOutsideWindow += 1;
    continue;
  }
  if (seen.has(item.url)) {
    droppedDuplicate += 1;
    continue;
  }
  seen.add(item.url);

  health.item_count += 1;
  if (health.status !== 'error') health.status = 'ok';
  feedHealthMap.set(health.source_name, health);

  kept.push({
    title: item.title,
    url: item.url,
    published: item.published.toISOString(),
    content: item.content,
    source_name: inferred.source_name,
    feed_url: inferred.feed_url || health.feed_url,
  });
}

kept.sort((a, b) => String(b.published).localeCompare(String(a.published)));

const generatedAt = new Date().toISOString();

return [{
  json: {
    generated_at: generatedAt,
    timezone: 'Europe/Paris',
    lookback_hours: LOOKBACK_HOURS,
    cutoff_iso: new Date(cutoffMs).toISOString(),
    feed_health: [...feedHealthMap.values()],
    stats: {
      incoming: incoming.length,
      kept: kept.length,
      dropped_no_url_or_title: droppedNoUrlOrTitle,
      dropped_undated: droppedUndated,
      dropped_outside_window: droppedOutsideWindow,
      dropped_duplicate: droppedDuplicate,
    },
    items: kept,
  },
}];

/**
 * Keyword-score every item in the 48h window, always keep official blog
 * posts, and only promote the highest-scoring arXiv papers up to a cap.
 */
const MAX_OFFICIAL = 20;
const MAX_ARXIV = 5;
const MAX_TOTAL = 16;
const MIN_ARXIV_SCORE = 3;

const KEYWORDS = [
  { label: 'openai', weight: 5, re: /\b(gpt-?\d|chatgpt|openai)\b/i },
  { label: 'anthropic', weight: 5, re: /\b(claude|anthropic)\b/i },
  { label: 'google', weight: 5, re: /\b(gemini|deepmind|antigravity|genie)\b/i },
  { label: 'huggingface', weight: 3, re: /\b(hugging\s?face|transformers|huggingface)\b/i },
  { label: 'markets', weight: 4, re: /\b(ipo|offering|nasdaq|placement)\b/i },
  { label: 'agents', weight: 3, re: /\b(agent|agents|agentic|multi-agent)\b/i },
  { label: 'eval', weight: 3, re: /\b(benchmark|eval(?:uation)?|leaderboard|swe-bench)\b/i },
  { label: 'safety', weight: 3, re: /\b(safety|alignment|safeguard|governance)\b/i },
  { label: 'release', weight: 2, re: /\b(release|launches|introducing|available now|is now available)\b/i },
  { label: 'research', weight: 2, re: /\b(research|paper|preprint|arxiv)\b/i },
  { label: 'model', weight: 1, re: /\b(api|model|llm|reasoning|multimodal)\b/i },
];

const payload = $input.first().json;
const items = Array.isArray(payload.items) ? payload.items : [];

function scoreItem(item) {
  const text = `${item.title || ''}\n${item.content || ''}`;
  const matched = [];
  let score = 0;
  for (const keyword of KEYWORDS) {
    if (keyword.re.test(text)) {
      score += keyword.weight;
      matched.push(keyword.label);
    }
  }
  const isArxiv = String(item.source_name || '').toLowerCase().includes('arxiv');
  if (!isArxiv) score += 2; // slight official-blog prior
  return { ...item, score, matched_keywords: matched, is_arxiv: isArxiv };
}

const scored = items.map(scoreItem);
const official = scored
  .filter((item) => !item.is_arxiv)
  .sort((a, b) => b.score - a.score || String(b.published).localeCompare(String(a.published)))
  .slice(0, MAX_OFFICIAL);
const arxiv = scored
  .filter((item) => item.is_arxiv && item.score >= MIN_ARXIV_SCORE)
  .sort((a, b) => b.score - a.score || String(b.published).localeCompare(String(a.published)))
  .slice(0, MAX_ARXIV);

// Official posts in the window come first, then the best arXiv papers, up to MAX_TOTAL.
const arxivSlots = Math.max(0, MAX_TOTAL - official.length);
const combined = [...official, ...arxiv.slice(0, arxivSlots)];

return [{
  json: {
    ...payload,
    items: scored,
    candidates: combined,
    ranking: {
      official_kept: official.length,
      arxiv_kept: arxiv.length,
      candidates: combined.length,
      min_arxiv_score: MIN_ARXIV_SCORE,
      max_total: MAX_TOTAL,
    },
  },
}];

/**
 * Build a single OpenAI-compatible chat request for every ranked candidate.
 * The model is forced to return JSON and to reuse the provided source URLs.
 * has_llm_key is false when OPENAI_API_KEY is unset, which skips the HTTP node.
 */
const payload = $input.first().json;
function readEnv(name, fallback) {
  try {
    const bag = (typeof $env !== 'undefined') ? $env : {};
    const value = bag[name];
    if (value == null || value === '') return fallback == null ? '' : fallback;
    return String(value);
  } catch {
    return fallback == null ? '' : fallback;
  }
}

const apiKey = readEnv('OPENAI_API_KEY', '').trim();
const model = readEnv('OPENAI_MODEL', 'gpt-4o-mini').trim() || 'gpt-4o-mini';
const baseUrl = readEnv('OPENAI_BASE_URL', 'https://api.openai.com/v1').replace(/\/$/, '');

const SYSTEM = [
  'You extract verifiable facts from official AI announcements and propose one post angle per article.',
  'Return a JSON object of the form {"ideas":[...]} and nothing else.',
  'Each idea MUST use this shape:',
  '{"title":string,"source_url":string,"source_name":string,"published":string,"facts":string[],"post_angle":string,"confidence":"high"|"medium"|"low"}',
  'Rules:',
  '- Copy source_url exactly as provided. Do not invent, shorten, or replace it.',
  '- Facts must be supported by the provided source text. Prefer close paraphrase over flourish.',
  '- Never invent figures, dates, names, product versions, or quotes.',
  '- If a number does not appear in the source text, do not use it.',
  '- If the source is thin, write fewer facts and set confidence to low.',
  '- post_angle is one sharp editorial angle, not a summary and not a published post.',
  '- Do not mention any agent, assistant, or tool by a personal name.',
].join('\n');

const articles = (payload.candidates || []).map((item) => ({
  title: item.title,
  source_url: item.url,
  source_name: item.source_name,
  published: item.published,
  source_text: String(item.content || '').slice(0, 4000),
  score: item.score,
  matched_keywords: item.matched_keywords,
}));

const llmRequest = {
  model,
  temperature: 0,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: SYSTEM },
    {
      role: 'user',
      content: `Extract facts and propose post angles for these ${articles.length} articles:\n${JSON.stringify({ articles }, null, 2)}`,
    },
  ],
};

return [{
  json: {
    ...payload,
    has_llm_key: apiKey.length > 0,
    llm_model: model,
    llm_url: `${baseUrl}/chat/completions`,
    llm_request: llmRequest,
  },
}];

/**
 * If the LLM returned valid JSON ideas, use them. Otherwise build a
 * conservative digest from the source titles and snippets only.
 * Facts in the fallback path are copied from the source text, never invented.
 *
 * After the HTTP node, n8n replaces the item with the API response, so this
 * node also re-reads the prepared payload from "Code · Prepare LLM request".
 */
function firstSentences(text, max = 3) {
  const clean = String(text || '').replace(/\s+/g, ' ').trim();
  if (!clean) return [];
  const parts = clean.split(/(?<=[.?!])\s+/).map((s) => s.trim()).filter((s) => s.length > 20);
  const unique = [];
  const seen = new Set();
  for (const part of parts) {
    const key = part.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    unique.push(part.length > 400 ? `${part.slice(0, 397)}...` : part);
    if (unique.length >= max) break;
  }
  return unique;
}

function fallbackIdeas(candidates) {
  return (candidates || []).map((item) => {
    const facts = firstSentences(item.content);
    if (facts.length === 0 && item.title) {
      facts.push(`Official title: ${item.title}`);
    }
    return {
      title: item.title,
      source_url: item.url,
      source_name: item.source_name,
      published: item.published,
      facts,
      post_angle: 'Needs human review — the LLM path was skipped or failed. Draft an angle only from the facts below.',
      confidence: 'low',
      llm_used: false,
      needs_review: true,
      score: item.score,
      matched_keywords: item.matched_keywords || [],
    };
  });
}

function pickCompletion(raw) {
  if (!raw || typeof raw !== 'object') return raw;
  if (raw.choices && raw.choices[0]) return raw.choices[0];
  if (raw.body) {
    const body = typeof raw.body === 'string' ? safeJson(raw.body) : raw.body;
    return pickCompletion(body);
  }
  return raw;
}

function safeJson(text) {
  if (text == null) return null;
  if (typeof text === 'object') return text;
  const str = String(text).trim();
  try { return JSON.parse(str); } catch { /* continue */ }
  const start = str.indexOf('{');
  const end = str.lastIndexOf('}');
  if (start >= 0 && end > start) {
    try { return JSON.parse(str.slice(start, end + 1)); } catch { return null; }
  }
  return null;
}

function ideasFromLlm(raw) {
  const choice = pickCompletion(raw);
  if (!choice) return null;
  const content = choice.message?.content || choice.content || choice;
  const parsed = safeJson(content);
  if (!parsed) return null;
  const list = Array.isArray(parsed.ideas) ? parsed.ideas : (Array.isArray(parsed) ? parsed : null);
  if (!list) return null;
  return list.map((idea) => ({
    title: idea.title || '',
    source_url: idea.source_url || idea.url || '',
    source_name: idea.source_name || '',
    published: idea.published || '',
    facts: Array.isArray(idea.facts) ? idea.facts.map((f) => String(f)) : [],
    post_angle: idea.post_angle || idea.angle || '',
    confidence: idea.confidence || 'medium',
    llm_used: true,
    needs_review: true,
  }));
}

const incoming = $input.first().json;
let prepared = incoming;
try {
  if (typeof $ === 'function') {
    const fromPrep = $('Code · Prepare LLM request').first().json;
    if (fromPrep && Array.isArray(fromPrep.candidates)) prepared = fromPrep;
  }
} catch { /* running outside n8n, or the skip-LLM path already has candidates */ }

if (!Array.isArray(prepared.candidates) && Array.isArray(incoming.candidates)) {
  prepared = incoming;
}

const httpLooksFailed = Boolean(incoming.error)
  || (incoming.statusCode && Number(incoming.statusCode) >= 400);
let llmError = null;
if (httpLooksFailed) {
  llmError = incoming.error?.message || incoming.error || incoming.message || `HTTP ${incoming.statusCode}`;
}

let ideas = null;
let llmUsed = false;
const shouldTryLlm = Boolean(prepared.has_llm_key) && (incoming !== prepared || incoming.choices || incoming.body);
if (shouldTryLlm && !httpLooksFailed) {
  try {
    ideas = ideasFromLlm(incoming);
    if (ideas && ideas.length) llmUsed = true;
    else llmError = llmError || 'LLM response did not contain a usable ideas array';
  } catch (err) {
    llmError = err.message || String(err);
  }
}

if (!llmUsed) {
  ideas = fallbackIdeas(prepared.candidates || []);
}

return [{
  json: {
    generated_at: prepared.generated_at,
    timezone: prepared.timezone || 'Europe/Paris',
    lookback_hours: prepared.lookback_hours,
    cutoff_iso: prepared.cutoff_iso,
    feed_health: prepared.feed_health,
    stats: prepared.stats,
    ranking: prepared.ranking,
    candidates: prepared.candidates,
    has_llm_key: Boolean(prepared.has_llm_key),
    llm_model: prepared.llm_model || null,
    llm_used: llmUsed,
    llm_error: llmError ? String(llmError) : null,
    ideas,
  },
}];

/**
 * Reject any idea that has no known source URL, or that uses a number
 * which does not appear in the source title, snippet, URL or date.
 * Accepted ideas stay flagged needs_review — nothing is published here.
 */
const payload = $input.first().json;
const candidates = payload.candidates || [];

function canonUrl(raw) {
  if (!raw) return '';
  try {
    const url = new URL(String(raw).trim());
    url.hash = '';
    for (const key of [...url.searchParams.keys()]) {
      if (key.toLowerCase().startsWith('utm_') || key === 'fbclid' || key === 'ref') {
        url.searchParams.delete(key);
      }
    }
    url.protocol = url.protocol === 'http:' ? 'https:' : url.protocol;
    let href = url.toString();
    if (href.endsWith('/') && url.pathname !== '/') href = href.slice(0, -1);
    return href;
  } catch {
    return String(raw).trim().replace(/\/$/, '');
  }
}

const byUrl = new Map();
for (const item of candidates) {
  byUrl.set(canonUrl(item.url), item);
}

function extractNumberTokens(text) {
  const matches = String(text || '').match(/\d{1,3}(?:,\d{3})+(?:\.\d+)?|\d+\.\d+|\d+/g) || [];
  return matches;
}

function variantsOf(token) {
  const raw = String(token);
  const noComma = raw.replace(/,/g, '');
  const asSet = new Set([raw, noComma]);
  if (/^\d+$/.test(noComma)) {
    asSet.add(noComma);
    // 1000 -> 1,000
    asSet.add(noComma.replace(/\B(?=(\d{3})+(?!\d))/g, ','));
  }
  if (raw.includes('.')) {
    const trimmed = raw.replace(/(\.\d*?)0+$/, '$1').replace(/\.$/, '');
    asSet.add(trimmed);
  }
  return [...asSet];
}

function numberInText(token, text) {
  const haystack = String(text || '');
  return variantsOf(token).some((variant) => haystack.includes(variant));
}

function allowedText(idea, source) {
  const parts = [
    idea.source_url,
    idea.source_name,
    idea.published,
    idea.title,
  ];
  if (source) {
    parts.push(source.title, source.content, source.url, source.published, source.source_name);
  }
  return parts.filter(Boolean).join('\n');
}

const accepted = [];
const rejected = [];

for (const idea of (payload.ideas || [])) {
  const reasons = [];
  const url = canonUrl(idea.source_url);
  const source = byUrl.get(url);
  if (!url) reasons.push('missing source_url');
  else if (!source) reasons.push('source_url does not match a fetched item');

  const haystack = allowedText(idea, source);
  const claimed = [
    ...(Array.isArray(idea.facts) ? idea.facts : []),
    idea.post_angle || '',
    idea.title || '',
  ].join('\n');

  const seenNums = new Set();
  for (const token of extractNumberTokens(claimed)) {
    const key = token.replace(/,/g, '');
    if (seenNums.has(key)) continue;
    seenNums.add(key);
    if (!numberInText(token, haystack)) {
      reasons.push(`number ${token} was not found in the source text`);
    }
  }

  const record = {
    ...idea,
    source_url: idea.source_url || '',
    needs_review: true,
    validation: reasons.length ? 'rejected' : 'accepted',
    rejection_reasons: reasons,
  };
  if (source && !record.source_name) record.source_name = source.source_name;
  if (source && !record.score) record.score = source.score;
  if (source && !record.matched_keywords) record.matched_keywords = source.matched_keywords;
  if (source && !record.published) record.published = source.published;
  (reasons.length ? rejected : accepted).push(record);
}

return [{
  json: {
    ...payload,
    accepted,
    rejected,
    ideas: accepted,
    validation_stats: {
      accepted: accepted.length,
      rejected: rejected.length,
    },
  },
}];

/**
 * Assemble a Markdown digest for human review. Every idea stays in
 * "needs review" — this workflow never publishes.
 */
const payload = $input.first().json;

function readEnv(name, fallback) {
  try {
    const bag = (typeof $env !== 'undefined') ? $env : {};
    const value = bag[name];
    if (value == null || value === '') return fallback == null ? '' : fallback;
    return String(value);
  } catch {
    return fallback == null ? '' : fallback;
  }
}


function formatParis(iso) {
  if (!iso) return '—';
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return String(iso);
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Europe/Paris',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  }).formatToParts(date);
  const get = (type) => parts.find((p) => p.type === type)?.value || '';
  return `${get('year')}-${get('month')}-${get('day')} ${get('hour')}:${get('minute')} Europe/Paris`;
}

function bullet(items) {
  if (!items || !items.length) return '- _None._';
  return items.map((x) => `- ${x}`).join('\n');
}

const generatedAt = payload.generated_at || new Date().toISOString();
const llmStatus = payload.llm_used
  ? `used (${payload.llm_model || 'model set in OPENAI_MODEL'})`
  : (payload.has_llm_key ? 'failed, fallback used' : 'skipped (no OPENAI_API_KEY)');

const healthLines = (payload.feed_health || []).map((feed) => {
  const name = feed.error
    ? `${feed.source_name} (${String(feed.error).replace(/\s+/g, ' ').slice(0, 120)})`
    : feed.source_name;
  return `| ${name} | ${feed.status} | ${feed.item_count} | ${feed.feed_url} |`;
});

function ideaBlock(idea, index) {
  const facts = (idea.facts || []).map((f) => `- ${f}`).join('\n') || '- _No extractable fact in the source snippet._';
  const keywords = (idea.matched_keywords || []).join(', ') || '—';
  const reasons = (idea.rejection_reasons || []).length
    ? `\n**Rejected because:** ${(idea.rejection_reasons || []).join('; ')}`
    : '';
  return [
    `### ${index}. ${idea.title}`,
    '',
    `- **Source:** [${idea.source_name || 'source'}](${idea.source_url})`,
    `- **Published:** ${formatParis(idea.published)}`,
    `- **Score:** ${idea.score ?? '—'} (${keywords})`,
    `- **Confidence:** ${idea.confidence || '—'}`,
    `- **LLM used:** ${idea.llm_used ? 'yes' : 'no'}`,
    `- **Status:** needs review${idea.validation === 'rejected' ? ' — rejected by validation' : ''}`,
    '',
    '**Facts (must come from the source):**',
    facts,
    '',
    `**Proposed angle:** ${idea.post_angle || '_None._'}`,
    reasons,
  ].join('\n');
}

const accepted = payload.accepted || payload.ideas || [];
const rejected = payload.rejected || [];
const stats = payload.stats || {};
const ranking = payload.ranking || {};

const lines = [
  '# AI Tech Watch — digest for human review',
  '',
  `Generated: **${formatParis(generatedAt)}**`,
  `Lookback window: **${payload.lookback_hours || 48} hours** (cutoff ${formatParis(payload.cutoff_iso)})`,
  `LLM: **${llmStatus}**`,
  payload.llm_error ? `LLM error: ${payload.llm_error}` : null,
  '',
  '> Nothing in this digest is published automatically. Every item is flagged `needs_review`.',
  '> Do not add figures that are not in the linked source. A human decides what, if anything, goes out.',
  '',
  '## Run statistics',
  '',
  `| Metric | Value |`,
  `| --- | ---: |`,
  `| Incoming feed items | ${stats.incoming ?? '—'} |`,
  `| Kept in the ${payload.lookback_hours || 48}h window (deduped) | ${stats.kept ?? '—'} |`,
  `| Dropped outside window | ${stats.dropped_outside_window ?? '—'} |`,
  `| Dropped duplicates | ${stats.dropped_duplicate ?? '—'} |`,
  `| Official posts kept | ${ranking.official_kept ?? '—'} |`,
  `| arXiv papers kept | ${ranking.arxiv_kept ?? '—'} |`,
  `| Candidates sent to LLM / fallback | ${ranking.candidates ?? accepted.length} |`,
  `| Ideas accepted by validation | ${(payload.validation_stats && payload.validation_stats.accepted) ?? accepted.length} |`,
  `| Ideas rejected by validation | ${(payload.validation_stats && payload.validation_stats.rejected) ?? rejected.length} |`,
  '',
  '## Feed health',
  '',
  '| Source | Status | Items in window | Feed URL |',
  '| --- | --- | ---: | --- |',
  ...(healthLines.length ? healthLines : ['| — | — | — | — |']),
  '',
  `## Ideas accepted for review (${accepted.length})`,
  '',
  accepted.length
    ? accepted.map((idea, i) => ideaBlock(idea, i + 1)).join('\n\n')
    : '_No idea passed validation in this run._',
  '',
  `## Rejected by validation (${rejected.length})`,
  '',
  rejected.length
    ? rejected.map((idea, i) => ideaBlock(idea, i + 1)).join('\n\n')
    : '_No idea was rejected._',
  '',
  '## What to do next',
  '',
  bullet([
    'Read each source URL before you reuse a fact.',
    'Rewrite the angle in your own voice if you decide to publish.',
    'Leave rejected ideas out, or fix them against the source and re-run.',
    'Optional Slack, Gmail and Sheets nodes stay off unless `ENABLE_NOTIFICATIONS=true` and credentials are set.',
  ]),
].filter((line) => line !== null);

const markdown = lines.join('\n') + '\n';

return [{
  json: {
    generated_at: generatedAt,
    timezone: 'Europe/Paris',
    lookback_hours: payload.lookback_hours,
    llm_used: payload.llm_used,
    has_llm_key: payload.has_llm_key,
    llm_error: payload.llm_error,
    needs_review: true,
    feed_health: payload.feed_health,
    stats: payload.stats,
    ranking: payload.ranking,
    validation_stats: payload.validation_stats,
    accepted_count: accepted.length,
    rejected_count: rejected.length,
    accepted,
    rejected,
    markdown,
    digest_filename: `ai-tech-watch-${formatParis(generatedAt).slice(0, 10)}.md`,
    digest_path: readEnv('DIGEST_PATH', '/tmp/ai-tech-watch-digest.md'),
    notifications_enabled: readEnv('ENABLE_NOTIFICATIONS', 'false') === 'true',
  },
}];

/**
 * Turn an n8n Error Trigger payload into a short Markdown incident note.
 */
const raw = $input.first().json;

function readEnv(name, fallback) {
  try {
    const bag = (typeof $env !== 'undefined') ? $env : {};
    const value = bag[name];
    if (value == null || value === '') return fallback == null ? '' : fallback;
    return String(value);
  } catch {
    return fallback == null ? '' : fallback;
  }
}

const now = new Date().toISOString();

function formatParis(iso) {
  const date = new Date(iso || Date.now());
  if (Number.isNaN(date.getTime())) return String(iso);
  return new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Europe/Paris',
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit',
    hour12: false,
  }).format(date).replace(',', '') + ' Europe/Paris';
}

const execution = raw.execution || raw;
const workflow = raw.workflow || {};
const error = execution.error || raw.error || raw;
const message = error.message || error.description || JSON.stringify(error);
const node = error.node || execution.lastNodeExecuted || 'unknown node';

const markdown = [
  '# AI Tech Watch — execution error',
  '',
  `Recorded: **${formatParis(now)}**`,
  `Workflow: **${workflow.name || 'AI Tech Watch'}**`,
  `Failed node: **${node}**`,
  '',
  '## Message',
  '',
  '```',
  String(message).slice(0, 2000),
  '```',
  '',
  'The official-feed requests are fail-open (`onError` continues the run).',
  'This note is for unhandled errors. Nothing was published.',
  '',
].join('\n');

return [{
  json: {
    generated_at: now,
    needs_review: true,
    error_message: String(message).slice(0, 2000),
    failed_node: node,
    markdown,
    digest_path: readEnv('ERROR_DIGEST_PATH', '/tmp/ai-tech-watch-error.md'),
  },
}];
